import React from 'react';
import styled from 'styled-components';
import Lottie from 'lottie-react'; // Adjust this import based on your setup
import animation1 from './path/to/animation1.json'; // Replace with your actual paths
import animation2 from './path/to/animation2.json';
import animation3 from './path/to/animation3.json';

const CTASection = styled(motion.section)`
  /* Your existing CTASection styles */
`;

const SectionsContainer = styled.div`
  display: flex;
  justify-content: space-around;
  flex-wrap: wrap; /* Allows wrapping for smaller screens */

  @media (max-width: 768px) {
    flex-direction: column;
    align-items: center;
  }
`;

const Section = styled.div`
  flex: 1;
  margin: 0 20px;
  max-width: 300px;
  text-align: center;

  @media (max-width: 768px) {
    margin: 20px 0;
    max-width: 80%;
  }
`;

const LottieContainer = styled.div`
  width: 160px;
  height: 160px; /* Fixed height for uniformity */
  margin: 0 auto; /* Center the animation */
  cursor: pointer;
  transition: transform 0.3s;

  &:hover {
    transform: scale(1.1);
  }
`;

const CTAHeading = styled.h2`
  font-size: 3.75rem;
  font-weight: 700;
  margin: 20px 0;
  color: white;
`;

const CTADescription = styled.p`
  margin-bottom: 40px;
  line-height: 1.5;
  font-size: 1rem;
  color: gray;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #007bff; /* Example color */
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 1rem;
  margin-top: 20px;

  &:hover {
    background-color: #0056b3; /* Darker shade on hover */
  }
`;

const CallToAction = () => {
  return (
    <CTASection initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <SectionsContainer>
        <Section>
          <CTAHeading>nexAR</CTAHeading>
          <LottieContainer>
            <Lottie animationData={animation2} loop={true} />
          </LottieContainer>
          <CTADescription>
            <strong>Luminexa Technologies developed image tracking virtual software based on Augmented Reality and Mixed Reality, named it nexAR.</strong>
          </CTADescription>
        </Section>
        
        <Section>
          <CTAHeading>How</CTAHeading>
          <LottieContainer>
            <Lottie animationData={animation1} loop={true} />
          </LottieContainer>
          <CTADescription>
            <strong>nexAR is a WebAR solution that displays content like 3D models, holographic avatars, videos, images, audio, and links when the nexAR camera is pointed at a 2D surface.</strong>
          </CTADescription>
        </Section>
        
        <Section>
          <CTAHeading>Works</CTAHeading>
          <LottieContainer>
            <Lottie animationData={animation3} loop={true} />
          </LottieContainer>
          <CTADescription>
            <strong>nexAR requires no additional app installations and works seamlessly on all smartphones, whether Android or iOS.</strong>
          </CTADescription>
        </Section>
      </SectionsContainer>
      <p style={{ color: 'white', margin: '19px' }}>
        <strong>Differentiate </strong> yourself from competition
      </p>
      <h1 style={{ color: 'white', fontSize: '80px' }}>Spark a Trend!</h1>
      <p style={{ color: 'gray', margin: '19px' }}>
        <strong>#nexAR #AugmentedReality #webAR</strong> Innovative Solution
      </p>
      <Button>Get Started</Button> {/* New button added here */}
    </CTASection>
  );
};

export default CallToAction;
